import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int k = sc.nextInt();

        List<Integer> digits = new ArrayList<>();
        while (n > 0) {
            digits.add((int)(n % k));
            n /= k;
        }

        int size = k + 1;
        long[][] matrix = new long[size][size];
        for (int j = 0; j <= k; ++j) {
            matrix[0][j] = 1;
            matrix[j][j] = 1;
        }

        // Matrix multiplication
        long[][] multiplyMatrices(long[][] A, long[][] B) {
            long[][] result = new long[size][size];
            for (int i = 0; i < size; ++i)
                for (int j = 0; j < size; ++j)
                    for (int t = 0; t < size; ++t)
                        result[i][j] = (result[i][j] + A[i][t] * B[t][j]) % MOD;
            return result;
        }

        // Matrix exponentiation
        long[][] matrixPower(long[][] base, long exp) {
            long[][] res = new long[size][size];
            for (int i = 0; i < size; ++i) res[i][i] = 1;
            while (exp > 0) {
                if ((exp & 1) == 1) res = multiplyMatrices(res, base);
                base = multiplyMatrices(base, base);
                exp >>= 1;
            }
            return res;
        }

        // jia_transform function
        long[][] jiaTransform(long[][] x, int d) {
            long[][] ret = new long[size][size];
            for (int i = 0; i <= k; ++i)
                for (int j = 0; j <= k; ++j) {
                    int ni = (i + d) % k;
                    int nj = (j + d) % k;
                    if (i == k) ni = k;
                    if (j == k) nj = k;
                    ret[ni][nj] = x[i][j];
                }
            return ret;
        }

        long[][] A = new long[size][size];
        for (int j = 0; j <= k; ++j) A[0][j] = 1;
        for (int j = 0; j <= k; ++j) A[j][j] = 1;

        long[][] baseA = A;
        long[][] ansA = A;

        long[][] ans = new long[size][size];
        for (int i = 0; i < size; ++i) ans[i][i] = 1;

        long idx = 0;
        for (int i = digits.size() - 1; i >= 0; --i) {
            int digit = digits.get(i);
            for (int j = 0; j < digit; ++j) {
                ans = multiplyMatrices(ans, jiaTransform(baseA, (j + (int)idx) % k));
            }
            idx = (idx + digit) % k;
        }

        long total = 0;
        for (int i = 0; i <= k; ++i) {
            total = (total + ans[i][k]) % MOD;
        }
        System.out.println(total);
        sc.close();
    }
}
